// EliteShipCatalogCheck: every ship design of the catalog (GENERATED by
// tools/colonization_lab/ship_designer.py) is a REAL runtime ship through the
// ONE generic path  ShipDesign -> ShipDescriptor -> ShipCore/ObjectModuleRuntime:
//   - module hierarchy: hull.root -> sections -> equipment; no missing parent,
//     no cycle, every support link resolves;
//   - physical control slots / generator groups bound to installed modules,
//     the passport coordinates registered as the loadout's actuator topology;
//   - devices created from passports (radar range, receiver, transmitter,
//     transponder, life support, jump core) and failing with their modules;
//   - CURRENT mass = attached modules + load; cargo / people / fluids change
//     acceleration; a detached train car leaves with its cargo;
//   - placement hit volumes, power, cooling, docks;
//   - fixed-step propulsion on the production control path for a small
//     Newtonian, an Assisted, C-120 empty/full, the jump train, the liner and
//     the line combatant;
//   - Cobrett: the passport (generic) ship against the legacy C++ Cobra.
// usage: EliteShipCatalogCheck [catalog.json]
#include <cmath>
#include <cstdlib>
#include <cstdio>
#include <iomanip>
#include <iostream>
#include <set>
#include <sstream>

#include "src/game/navigation/DynamicMotionState.h"
#include "src/game/catalog/ships/ShipCargoPassports.h"
#include "src/game/ship/ShipInitData.h"
#include "src/game/ship/core/ShipCore.h"
#include "src/game/ship/descriptors/CatalogShipRegistry.h"
#include "src/game/ship/descriptors/EliteCobraMk1.h"

namespace
{
int failures = 0;

void check(bool ok, const std::string& what)
{
    std::cout << (ok ? "PASS " : "FAIL ") << what << "\n";
    if (!ok)
        ++failures;
}

std::string num(double v, int digits = 3)
{
    std::ostringstream s;
    s << std::fixed << std::setprecision(digits) << v;
    return s.str();
}

constexpr double G0 = 9.80665;

const ModuleDescriptor* moduleOf(const ShipDescriptor& d, const std::string& id)
{
    for (const auto& m : d.modules)
        if (m.moduleId == id)
            return &m;
    return nullptr;
}

std::unique_ptr<game::ship::core::ShipCore> spawn(const ShipDescriptor& d)
{
    auto core = std::make_unique<game::ship::core::ShipCore>();
    core->init(ShipRole::NPC, d, glm::vec3(0.0f), ShipInitData {}, glm::mat4(1.0f));
    core->refreshRuntimeState();
    return core;
}

// Production control path in a local tactical frame: full forward main for
// `seconds`; returns the mean body-frame forward acceleration over the last
// half of the burn and the peak angular rate (an unbalanced r x F spins it).
struct BurnResult
{
    double forwardMps2 = 0.0;
    double peakRateRadPerSec = 0.0;
};

BurnResult burn(game::ship::core::ShipCore& core, double seconds)
{
    auto& tr = core.transform();
    tr.motion.mode = game::navigation::MotionMode::HubTactical;
    tr.motion.travelFrame.systemId = 0;
    tr.motion.travelFrame.frameId = "ship-catalog-check";
    tr.motion.travelFrame.originMeters = glm::dvec3(0.0);
    tr.motion.travelFrame.localToWorldBasis = glm::dmat3(1.0);
    tr.motion.travelFrame.valid = true;
    tr.motion.localPositionMeters = glm::dvec3(0.0);
    tr.motion.localVelocityMps = glm::dvec3(0.0);
    tr.motion.worldVelocityMps = glm::dvec3(0.0);
    const bool assisted = game::ship::plant::familyOf(core.state().construction.physicalControlModel) ==
                          game::ship::plant::PhysicalControlFamily::Assisted;
    const double dt = 1.0 / 60.0;
    const int steps = static_cast<int>(seconds / dt);
    glm::dvec3 vHalf {0.0};
    BurnResult out;
    for (int i = 0; i < steps; ++i)
    {
        auto& c = core.control();
        c.targetSpeedRate = 1.0f;
        c.assistedMaxSpeedCommand = assisted;
        core.updateTranslationControl(static_cast<float>(dt));
        core.propagateMotionOrientation(static_cast<float>(dt));
        (void)core.propagateHubTacticalTranslation(dt);
        core.updateSystems(static_cast<float>(dt));
        out.peakRateRadPerSec = std::max({out.peakRateRadPerSec, std::abs(static_cast<double>(tr.pitchRate)),
                                          std::abs(static_cast<double>(tr.yawRate)), std::abs(static_cast<double>(tr.rollRate))});
        if (i == steps / 2)
            vHalf = tr.motion.localVelocityMps;
        if (std::getenv("ELITE_SHIP_CHECK_TRACE") && i % 30 == 0)
        {
            const auto& t = tr.motion.engineTelemetry;
            std::cout << "       t " << num(i * dt, 2) << " v " << num(glm::length(tr.motion.localVelocityMps), 2);
            for (int e = 0; e < t.count; ++e)
                std::cout << " | e" << e << " thr " << num(t.thrust01[e], 2) << " av " << num(t.available01[e], 2) << " F "
                          << num(glm::length(t.forceBodyNewtons[e]) / 1e6, 2) << " MW " << num(t.electricalMW[e], 0);
            std::cout << std::endl;
        }
    }
    const glm::dvec3 dv = tr.motion.localVelocityMps - vHalf;
    out.forwardMps2 = glm::length(dv) / (dt * (steps - steps / 2 - 1));
    return out;
}

double ratedThrustN(const ShipDescriptor& d)
{
    double n = 0.0;
    for (const auto& id : d.mainPropulsion.aftEngineModuleIds)
        if (const auto* m = moduleOf(d, id); m && m->engine)
            n += m->engine->nominalThrustNewtons;
    return n;
}
} // namespace

int main(int argc, char** argv)
{
    using namespace game::catalog::ships;
    using game::ship::descriptors::CatalogShipRegistry;
    auto& catalog = const_cast<ShipDesignCatalog&>(ShipDesignCatalog::instance());
    const std::string path = argc > 1 ? argv[1] : "src/assets/data/ships/ship_catalog_3126.json";
    if (catalog.ships().empty())
        check(catalog.load(path), "ship catalog loads (" + path + ")");
    check(catalog.ships().size() >= 17, std::to_string(catalog.ships().size()) + " ship designs (17 classes + variants)");

    std::set<std::string> classes;
    for (const auto& s : catalog.ships())
    {
        classes.insert(s.shipClass);
        const ShipDescriptor* d = CatalogShipRegistry::instance().find(s.id);
        check(d != nullptr, s.id + ": descriptor builds" + (d ? "" : " (" + CatalogShipRegistry::instance().errorOf(s.id) + ")"));
        if (!d)
            continue;
        const auto& loadout = d->loadouts.front();
        check(d->typeId == ObjectType::None && d->catalog.passportId == s.id && loadout.shipPassportId == s.id &&
                  loadout.topologyKey != 0 && game::ship::plant::findActuatorTopology(loadout.topologyKey),
              s.id + ": identity = passport id (no ObjectType), loadout topology registered");

        // ---- passport coordinates ARE the loadout's mount positions
        bool coordinates = true;
        for (const auto& item : s.installed)
            if (item.category == "drive")
                for (std::size_t k = 0; k < item.slots.size(); ++k)
                    for (const auto& slot : loadout.propulsionSlots)
                        if (item.slots[k] == slot.id)
                            coordinates = coordinates && glm::length(slot.normalizedPositionBody - item.positions[k]) < 1e-9;
        check(coordinates, s.id + ": main slot coordinates from the passport (" + s.physicalModel + ")");

        auto core = spawn(*d);
        const auto& runtime = core->moduleRuntime();

        // ---- module hierarchy
        int missingParents = 0, cycles = 0, badSupports = 0, deepest = 0;
        for (const auto& m : d->modules)
        {
            const auto* st = runtime.findModule(m.moduleId);
            if (!st)
            {
                ++missingParents;
                continue;
            }
            if (!m.parentModuleId.empty() && st->parentIndex < 0)
                ++missingParents;
            for (const auto& sup : m.supportModuleIds)
                badSupports += runtime.findModule(sup) ? 0 : 1;
            // walk to the root: every chain ends at hull.root within the module count
            int depth = 0;
            const world::modules::ObjectModuleState* walk = st;
            std::string reached = m.moduleId;
            while (walk && !walk->parentModuleId.empty() && depth <= static_cast<int>(d->modules.size()))
            {
                reached = walk->parentModuleId;
                walk = runtime.findModule(walk->parentModuleId);
                ++depth;
            }
            if (!walk || depth > static_cast<int>(d->modules.size()) || reached != game::ship::descriptors::HullRootModuleId)
                cycles += m.moduleId == game::ship::descriptors::HullRootModuleId ? 0 : 1;
            deepest = std::max(deepest, depth);
        }
        check(missingParents == 0 && cycles == 0 && badSupports == 0 && runtime.findModule("hull.root"),
              s.id + ": " + std::to_string(d->modules.size()) + " modules under hull.root (depth " + std::to_string(deepest) +
                  "): missing parents " + std::to_string(missingParents) + ", broken chains " + std::to_string(cycles) +
                  ", unresolved supports " + std::to_string(badSupports));

        // ---- construction: slots, generator groups, services
        const auto& slots = core->state().actuators.propulsionSlots;
        bool slotsOk = core->state().valid() && slots.size() == loadout.propulsionSlots.size();
        for (const auto& sl : slots)
            slotsOk = slotsOk && sl.operational && sl.thrust01 > 0.99;
        bool groupsOk = !loadout.engineReactorGroups.empty();
        double ratedMWe = 0.0;
        for (std::size_t g = 0; g < loadout.engineReactorGroups.size(); ++g)
        {
            const auto* m = moduleOf(*d, loadout.engineReactorGroups[g].reactorModuleId);
            groupsOk = groupsOk && m && m->engineReactor && core->engineReactorAvailableMW(g) > 0.0;
            if (m && m->engineReactor)
                ratedMWe += m->engineReactor->ratedElectricalMW;
        }
        check(slotsOk && groupsOk && std::abs(ratedMWe - s.propulsionMWe) < 1e-6 &&
                  moduleOf(*d, d->powerThermalInstallation.shipReactorModuleId) &&
                  moduleOf(*d, d->powerThermalInstallation.commonCoolingModuleId),
              s.id + ": " + std::to_string(slots.size()) + " control slots healthy, " + std::to_string(loadout.engineReactorGroups.size()) +
                  " generator groups live (" + num(ratedMWe, 0) + " MWe = passport), service reactor + coolant loop bound");

        // ---- devices from passports
        const auto& dev = core->devices();
        const auto* radarItem = s.firstOf("radar");
        double passportRange = 0.0;
        for (const auto* r : s.allOf("radar"))
            passportRange = std::max(passportRange, catalog.findProduct(r->productId)->number("range_km") * 1000.0);
        const bool hasCore = s.firstOf("jump_core") != nullptr;
        check(radarItem && dev.radar && std::abs(core->radar().getDesc().maxRange - passportRange) < 1e-6 &&
                  dev.radarRangeMeters == passportRange && dev.receiver && dev.transmitter && dev.lifeSupport && dev.computer &&
                  dev.jumpCore == hasCore && (!s.firstOf("transponder") || dev.transponder),
              s.id + ": devices live - radar " + num(passportRange / 1000.0, 0) + " km (passport), receiver, transmitter, life support, computer" +
                  (hasCore ? ", jump core " + num(d->catalog.jumpCoreRatingTonnes, 0) + " t" : ", no jump core (in-system)"));

        // ---- current mass and load
        // one mass ladder: the passport service mass IS the runtime spawn mass
        const double serviceKg = s.serviceTonnes * 1000.0;
        check(std::abs(core->currentMassKg() - serviceKg) < 10.0 && std::abs(d->physics.massKg - s.dryMassTonnes * 1000.0) < 1.0 &&
                  std::abs(s.c20TareTonnes - ::catalog::ships::C20TareTonnes) < 1e-12 &&
                  std::abs(s.grossTonnes - (s.serviceTonnes + s.netPayloadTonnes + s.containerTareTonnes)) < 0.02,
              s.id + ": service mass " + num(core->currentMassKg() / 1000.0, 2) + " t = passport service_t; passport gross = service + net + C20 tare (" +
                  num(s.c20TareTonnes, 1) + " t = runtime C20 tare)");
        const double aLight = core->capabilities().effectivePhysics.forwardMainEngineAccelerationMps2;
        auto full = game::ship::core::ShipCore::serviceLoad(*d);
        full.persons = s.crew + s.passengers;
        full.cargoTonnes = s.cargoTonnes;
        // "Full passport load" means every declared C20 place is occupied.
        // This matters for mass-limited hulls such as OCS-4: 409 t net is
        // spread across 24 containers, not packed into the minimum 21.
        full.containers = s.containerSlots;
        core->setLoad(full);
        const int boxes = s.containerSlots;
        const double grossKg = s.grossTonnes * 1000.0;   // gross includes the C20 tare
        const double aFull = core->capabilities().effectivePhysics.forwardMainEngineAccelerationMps2;
        const double thrust = ratedThrustN(*d);
        const bool carries = s.cargoTonnes > 0.0 || s.passengers > 0;
        if (std::abs(core->currentMassKg() - grossKg) >= 10.0 || std::abs(aFull - thrust / core->currentMassKg()) >= 1e-3 * aFull ||
            std::abs(thrust - s.thrustMN * 1e6) >= 1e-3 * thrust)
            std::cout << "     detail: mass " << num(core->currentMassKg(), 1) << " kg vs " << num(grossKg, 1) << ", a " << aFull << " vs "
                      << thrust / core->currentMassKg() << ", thrust " << thrust << " vs passport " << s.thrustMN * 1e6 << std::endl;
        // the passport gross is rounded to 0.01 t
        check(std::abs(core->currentMassKg() - grossKg) < 10.0 &&
                  std::abs(aFull - thrust / core->currentMassKg()) < 1e-3 * aFull && (!carries || aFull < aLight * (1.0 - 1e-6)) &&
                  std::abs(thrust - s.thrustMN * 1e6) < 1e-3 * thrust,
              s.id + ": loaded " + num(core->currentMassKg() / 1000.0, 0) + " t = passport gross " + num(s.grossTonnes, 2) + " t (incl. " +
                  std::to_string(boxes) + " C20 tare) -> " + num(aFull / G0) + " g vs " + num(aLight / G0) + " g in service");

        // ---- docks, cooling, hit volumes
        int dockPorts = s.countOf("docking_port") + s.countOf("boat_bay") + s.countOf("drone_bay") + s.countOf("hangar");
        int placed = 0;
        for (const auto& m : d->modules)
            placed += m.placement.valid ? 1 : 0;
        check(dev.dockPortsOperational == dockPorts && std::abs(d->cooling.radiatorArea - s.radiatorAreaM2) < 1e-9 &&
                  static_cast<int>(core->hitComponent().volumes.size()) == placed && !d->primitiveBlocks.empty(),
              s.id + ": " + std::to_string(dockPorts) + " docks/bays, " + num(s.radiatorAreaM2, 0) + " m2 radiators, " +
                  std::to_string(placed) + " placement hit volumes, " + std::to_string(d->primitiveBlocks.size()) + " primitive blocks");

        // ---- damage through ObjectModuleRuntime
        const std::string radarModule = d->catalog.radarModuleIds.front();
        const bool destroyed = core->debugDestroyModuleById(radarModule);
        core->refreshRuntimeState();
        core->refreshDeviceState();
        const bool radarGone = d->catalog.radarModuleIds.size() > 1 ? core->devices().radar : !core->devices().radar;
        const std::string driveModule = d->mainPropulsion.aftEngineModuleIds.front();
        core->debugDestroyModuleById(driveModule);
        core->refreshRuntimeState();
        const double aDamaged = core->capabilities().effectivePhysics.forwardMainEngineAccelerationMps2;
        check(destroyed && radarGone && aDamaged < aFull * 0.999,
              s.id + ": radar module destroyed -> radar " + (core->devices().radar ? "kept by the second set" : "off") +
                  "; drive destroyed -> forward " + num(aDamaged / G0) + " g");

        std::cout << "     " << std::left << std::setw(30) << s.name << " " << std::setw(11) << s.physicalModel << " " << std::right
                  << std::setw(4) << d->modules.size() << " modules, CoM z " << num(d->physics.centerOfMassLocalMeters.z, 2) << " m, I "
                  << num(d->physics.pitchInertiaKgM2 / 1e6, 1) << "/" << num(d->physics.yawInertiaKgM2 / 1e6, 1) << "/"
                  << num(d->physics.rollInertiaKgM2 / 1e6, 1) << " Mkg m2, " << num(aLight / G0, 2) << " g service, "
                  << num(aFull / G0, 2) << " g loaded\n";
    }
    check(classes.size() == 18, std::to_string(classes.size()) + " economic classes covered (17 fleet classes; tankers split jump / gas)");

    // ---- train: a detached car leaves with its share of the cargo
    if (const auto* train = CatalogShipRegistry::instance().find("harmony.ship.he-t12.lokomotiv"))
    {
        auto core = spawn(*train);
        auto load = game::ship::core::ShipCore::serviceLoad(*train);
        load.cargoTonnes = train->storage.cargoMass;
        core->setLoad(load);
        const double before = core->currentMassKg();
        const auto boxesAboard = [&](double cargo) {
            return std::min(
                train->storage.containerSlots,
                static_cast<int>(std::ceil(cargo / ::catalog::ships::C20PayloadTonnes))
            );
        };
        const double aBefore = core->capabilities().effectivePhysics.forwardMainEngineAccelerationMps2;
        const std::string car = train->catalog.cargoHolderModuleIds.front();
        const bool detached = core->debugDetachModuleById(car);
        core->refreshRuntimeState();
        const auto* m = moduleOf(*train, car);
        const double carCargo = train->catalog.cargoHolderCapacityTonnes.front();
        // the car leaves with its cargo and the C20 boxes that carried it
        const double carKg =
            m->placement.massKg + carCargo * 1000.0 +
            (boxesAboard(load.cargoTonnes) - boxesAboard(load.cargoTonnes - carCargo)) *
                ::catalog::ships::C20TareTonnes * 1000.0;
        const bool fragmentSpawned =
            core->detachedFragmentRuntime().hasFragment(car);
        const auto* fragment =
            core->detachedFragmentRuntime().findFragment(car);
        const bool fragmentAtPassportPosition =
            fragment &&
            glm::length(fragment->homeCenterLocal - m->placement.centerMeters) < 1.0e-4f &&
            glm::length(fragment->position - m->placement.centerMeters) < 1.0e-4f;
        const double detachedMassKg = core->currentMassKg();
        const double aDetached = core->capabilities().effectivePhysics.forwardMainEngineAccelerationMps2;
        const bool reattached = core->debugReattachModuleById(car);
        core->refreshRuntimeState();
        check(detached && fragmentSpawned && fragmentAtPassportPosition &&
                  std::abs((before - detachedMassKg) - carKg) < 1e-3 * carKg &&
                  aDetached > aBefore &&
                  reattached && std::abs(core->currentMassKg() - before) < 1e-6 * before,
              "He-T12 train: detached car becomes a fragment at its passport position, removes " +
                  num((before - detachedMassKg) / 1000.0, 0) +
                  " t (car + cargo + C20), then reattaches with mass restored");
    }

    // ---- fixed-step propulsion on the production control path
    struct Case
    {
        const char* id;
        const char* what;
        bool loaded;
    };
    for (const Case c : {Case {"ofu.ship.ocs-4.lastochka", "small Newtonian", false},
                         Case {"sol.ship.pk-30.strazh", "Assisted", false},
                         Case {"bharat.ship.c-120.konveyer", "C-120 empty", false},
                         Case {"bharat.ship.c-120.konveyer", "C-120 full", true},
                         Case {"harmony.ship.he-t12.lokomotiv", "jump train full", true},
                         Case {"hyp.ship.l-900.piligrim", "liner full", true},
                         Case {"bastion.ship.b-90.tsitadel", "line combatant", false},
                         Case {"kb.ship.cobrett-i.frnu.n1", "Cobrett-I N1 (passport)", false},
                         Case {"kb.ship.cobrett-i.frnu-inta.a3", "Cobrett-I A3 (passport, Assisted)", false},
                         Case {"bastion.ship.b-4.sokol", "interceptor (Assisted X)", false},
                         Case {"sol.ship.st-6.masterovoy", "service tender (Assisted I)", false}})
    {
        const auto* d = CatalogShipRegistry::instance().find(c.id);
        if (!d)
        {
            check(false, std::string(c.what) + ": " + c.id + " missing");
            continue;
        }
        auto core = spawn(*d);
        auto load = game::ship::core::ShipCore::serviceLoad(*d);
        if (c.loaded)
        {
            load.persons = d->catalog.crew + d->catalog.passengers;
            load.cargoTonnes = d->storage.cargoMass;
        }
        core->setLoad(load);
        const double expected = core->capabilities().effectivePhysics.forwardMainEngineAccelerationMps2;
        // what the engines can do, bounded by the crew-load envelope (passengers / detainees: 1.5 g x 1.5)
        const double engines = ratedThrustN(*d) / core->currentMassKg();
        const double physical = std::min(engines, static_cast<double>(d->physics.maxLinearGs) * G0);
        const auto r = burn(*core, 4.0);
        std::cout << "     CoM " << num(core->state().massProperties.centerOfMassLocalMeters.x, 3) << ", "
                  << num(core->state().massProperties.centerOfMassLocalMeters.y, 3) << ", "
                  << num(core->state().massProperties.centerOfMassLocalMeters.z, 3) << " m; working axis emergency "
                  << core->capabilities().effectivePhysics.assistedWorkingThrustAxisEmergency << std::endl;
        check(std::abs(r.forwardMps2 - physical) < 0.05 * physical && std::abs(expected - engines) < 1e-3 * engines &&
                  r.peakRateRadPerSec < 0.02,
              std::string("burn ") + c.what + ": " + num(r.forwardMps2, 3) + " m/s2 measured vs thrust/mass " + num(engines, 3) +
                  (physical < engines ? " capped by the crew load " + num(physical, 3) : std::string()) +
                  " m/s2 (" + num(core->currentMassKg() / 1000.0, 0) + " t), peak spin " + num(r.peakRateRadPerSec, 4) + " rad/s");
    }

    // ---- reference: the legacy C++ Cobra on the same harness (control-law behaviour, not the generic path)
    for (const auto model : {game::ship::plant::PhysicalControlModelId::NewtonianI, game::ship::plant::PhysicalControlModelId::AssistedI})
    {
        auto core = spawn(EliteCobraMk1::EliteCobraMk1Descriptor());
        core->selectPhysicalConstructionForDiagnostic(model);
        core->refreshRuntimeState();
        const double physical = ratedThrustN(core->descriptor()) / core->currentMassKg();
        const auto r = burn(*core, 4.0);
        std::cout << "     reference legacy Cobra " << game::ship::plant::physicalControlModelName(model) << ": " << num(r.forwardMps2, 3)
                  << " m/s2 measured vs thrust/mass " << num(physical, 3) << " m/s2" << std::endl;
        for (const double dy : {0.02, 0.05, 0.1, 0.2})
        {
            auto shifted = spawn(EliteCobraMk1::EliteCobraMk1Descriptor());
            shifted->selectPhysicalConstructionForDiagnostic(model);
            shifted->refreshRuntimeState();
            shifted->state().massProperties.centerOfMassLocalMeters.y = dy;
            shifted->state().massProperties.touch();
            const auto q = burn(*shifted, 4.0);
            std::cout << "       CoM y +" << dy << " m: " << num(q.forwardMps2, 3) << " m/s2, emergency axis "
                      << shifted->capabilities().effectivePhysics.assistedWorkingThrustAxisEmergency << std::endl;
        }
    }

    // ---- Cobrett: passport ship vs legacy C++ Cobra
    {
        using game::ship::plant::PhysicalControlModelId;
        const auto& legacy = EliteCobraMk1::EliteCobraMk1Descriptor();
        for (const auto& [passport, model] : {std::pair<const char*, PhysicalControlModelId> {"kb.ship.cobrett-i.frnu.n1", PhysicalControlModelId::NewtonianI},
                                              {"kb.ship.cobrett-i.frnu-inta.a3", PhysicalControlModelId::AssistedI}})
        {
            const auto* g = CatalogShipRegistry::instance().find(passport);
            const auto* lo = legacy.findLoadout(model);
            if (!g || !lo)
            {
                check(false, std::string(passport) + ": both descriptors exist");
                continue;
            }
            const auto& go = g->loadouts.front();
            bool slots = go.propulsionSlots.size() == lo->propulsionSlots.size();
            bool engines = slots;
            for (std::size_t i = 0; slots && i < go.propulsionSlots.size(); ++i)
            {
                slots = slots && std::string(go.propulsionSlots[i].id) == lo->propulsionSlots[i].id &&
                        glm::length(go.propulsionSlots[i].normalizedPositionBody - lo->propulsionSlots[i].normalizedPositionBody) < 1e-9;
                const auto* a = moduleOf(*g, go.propulsionModuleIds[i]);
                const auto* b = moduleOf(legacy, lo->propulsionModuleIds[i]);
                engines = engines && a && b && a->engine && b->engine && a->engine->engineTypeId == b->engine->engineTypeId &&
                          a->engine->nominalThrustNewtons == b->engine->nominalThrustNewtons &&
                          a->engine->nominalElectricalPowerMW == b->engine->nominalElectricalPowerMW &&
                          a->engine->nominalGimbalRangeRad == b->engine->nominalGimbalRangeRad;
            }
            bool nozzles = go.rcsNozzles.size() == lo->rcsNozzles.size();
            for (std::size_t i = 0; nozzles && i < go.rcsNozzles.size(); ++i)
            {
                const auto* a = moduleOf(*g, go.rcsNozzles[i].nozzleId);
                const auto* b = moduleOf(legacy, lo->rcsNozzles[i].nozzleId);
                nozzles = nozzles && go.rcsNozzles[i].nodeId == lo->rcsNozzles[i].nodeId &&
                          glm::length(go.rcsNozzles[i].positionBody - lo->rcsNozzles[i].positionBody) < 1e-9 &&
                          go.rcsNozzles[i].forceDirectionBody == lo->rcsNozzles[i].forceDirectionBody && a && b && a->engine && b->engine &&
                          a->engine->nominalThrustNewtons == b->engine->nominalThrustNewtons &&
                          a->engine->nominalElectricalPowerMW == b->engine->nominalElectricalPowerMW;
            }
            bool reactors = go.engineReactorGroups.size() == lo->engineReactorGroups.size();
            for (std::size_t i = 0; reactors && i < go.engineReactorGroups.size(); ++i)
            {
                const auto* a = moduleOf(*g, go.engineReactorGroups[i].reactorModuleId);
                const auto* b = moduleOf(legacy, lo->engineReactorGroups[i].reactorModuleId);
                reactors = reactors && go.engineReactorGroups[i].slotId == lo->engineReactorGroups[i].slotId &&
                           go.engineReactorGroups[i].poweredEngineSlotIds == lo->engineReactorGroups[i].poweredEngineSlotIds &&
                           glm::length(go.engineReactorGroups[i].normalizedPositionBody - lo->engineReactorGroups[i].normalizedPositionBody) < 1e-9 &&
                           a && b && a->engineReactor && b->engineReactor && a->engineReactor->typeId == b->engineReactor->typeId &&
                           a->engineReactor->ratedElectricalMW == b->engineReactor->ratedElectricalMW;
            }
            const auto& gd = g->logicalDimensionsValue;
            const auto& ld = legacy.logicalDimensionsValue;
            const bool hull = std::abs(g->physics.massKg - legacy.physics.massKg) < 1.0 && gd.length == ld.length && gd.width == ld.width &&
                              gd.height == ld.height && std::abs(g->reactor.nominalPowerMW - legacy.reactor.nominalPowerMW) < 1e-9 &&
                              std::abs(g->cooling.radiatorArea - legacy.cooling.radiatorArea) < 1e-9 &&
                              g->storage.containerSlots == legacy.storage.containerSlots;
            // The legacy C++ Cobra is ONE hull for both generations and carries the N1 hold;
            // the A3 passport hold is smaller (its four drives). Reported, not hidden.
            if (g->storage.cargoMass != legacy.storage.cargoMass)
                std::cout << "     NOTE " << passport << ": passport hold " << g->storage.cargoMass << " t, legacy Cobra hold "
                          << legacy.storage.cargoMass << " t (legacy has one hold for both generations)" << std::endl;
            if (!hull)
                std::cout << "     detail: mass " << g->physics.massKg << "/" << legacy.physics.massKg << ", L " << gd.length << "/" << ld.length
                          << ", W " << gd.width << "/" << ld.width << ", H " << gd.height << "/" << ld.height << ", SR "
                          << g->reactor.nominalPowerMW << "/" << legacy.reactor.nominalPowerMW << ", radiators " << g->cooling.radiatorArea << "/"
                          << legacy.cooling.radiatorArea << ", hold " << g->storage.cargoMass << "/" << legacy.storage.cargoMass << ", C20 "
                          << g->storage.containerSlots << "/" << legacy.storage.containerSlots << std::endl;
            check(slots && engines && nozzles && reactors && hull,
                  std::string(passport) + " vs legacy Cobra " + game::ship::plant::physicalControlModelName(model) +
                      ": slot coordinates " + (slots ? "=" : "!=") + ", drives " + (engines ? "=" : "!=") + ", 24 nozzles " +
                      (go.rcsNozzles.empty() ? "n/a" : (nozzles ? "=" : "!=")) + ", generators " + (reactors ? "=" : "!=") +
                      ", hull (mass, envelope, SR-70, radiators, C20) " + (hull ? "=" : "!="));
            std::cout << "     inertia passport/legacy: pitch " << num(g->physics.pitchInertiaKgM2 / legacy.physics.pitchInertiaKgM2)
                      << ", yaw " << num(g->physics.yawInertiaKgM2 / legacy.physics.yawInertiaKgM2) << ", roll "
                      << num(g->physics.rollInertiaKgM2 / legacy.physics.rollInertiaKgM2) << " (passport sums its module boxes; legacy is one uniform box)\n";
        }
    }

    std::cout << (failures ? "SHIP CATALOG CHECK: FAILED (" + std::to_string(failures) + ")" : "SHIP CATALOG CHECK: PASS") << "\n";
    return failures ? 1 : 0;
}
